// Exact binary singular-point screening and Hasse--Witt invariants for (3,3) curves.
#include <bits/stdc++.h>
using namespace std;
static constexpr int DEG[]={0,1,2,3,4,5,6};
static constexpr int IRR[]={0,0x3,0x7,0xb,0x13,0x25,0x43};
struct FField {int m,n,poly; int mul(int a,int b)const{int r=0;while(b){if(b&1)r^=a;b>>=1;a<<=1;if(a&n)a^=poly;}return r;} int pow(int x,int e)const{int z=1;while(e){if(e&1)z=mul(z,x);x=mul(x,x);e>>=1;}return z;} };
int rank4(array<int,4> rows){int r=0;for(int k=0;k<4;++k){int l=-1;for(int i=r;i<4;++i)if(rows[i]>>k&1){l=i;break;}if(l<0)continue;swap(rows[r],rows[l]);for(int i=0;i<4;++i)if(i!=r && (rows[i]>>k&1))rows[i]^=rows[r];++r;}return r;}
array<int,4> matmult(array<int,4>A,array<int,4>B){array<int,4>C={};for(int i=0;i<4;++i)for(int k=0;k<4;++k)if(A[i]>>k&1)C[i]^=B[k];return C;}
int points1(int mask){int count=0;for(int a=0;a<3;++a)for(int b=0;b<3;++b){int x=a==2?0:a,y=b==2?0:b,ss=0;for(int i=0;i<4;++i)for(int j=0;j<4;++j)if(mask>>(i*4+j)&1){int ei=a==2?3-i:i,ej=b==2?3-j:j;if((!ei||x)&&(!ej||y))ss^=1;}if(!ss)++count;}return count;}
array<int,4> hasse(int mask){array<int,4>H={};int a[4][2]={{1,1},{1,2},{2,1},{2,2}};for(int row=0;row<4;++row)for(int col=0;col<4;++col){int ei=2*a[col][0]-a[row][0],ej=2*a[col][1]-a[row][1];if(ei>=0&&ei<=3&&ej>=0&&ej<=3&&(mask>>(ei*4+ej)&1))H[row]|=1<<col;}return H;}
void mark_kernel(vector<unsigned char>& singular, vector<int>&cert, vector<int>&rows, int m, int ax, int by){int piv[16]={},r=0;for(int v:rows){for(int c=0;c<16;++c)if((v>>c)&1){if(piv[c])v^=piv[c];else{piv[c]=v;r++;break;}}}int freecols[16],nf=0;for(int c=0;c<16;++c)if(!piv[c])freecols[nf++]=c;
 vector<int> basis(nf);for(int z=0;z<nf;++z){int w=1<<freecols[z];for(int c=15;c>=0;--c)if(piv[c]){int t=piv[c] & (~((1<<(c+1))-1)); if(__builtin_parity((unsigned)(t&w)))w|=1<<c;}basis[z]=w;}
 int last=0;for(int g=1;g<(1<<nf);++g){int k=__builtin_ctz((unsigned)g);last^=basis[k];singular[last]=1;if(!cert[last])cert[last]=(m<<16)|(ax<<8)|by;}
}
int main(int argc,char**argv){vector<unsigned char>sing(65536,0);vector<int>cert(65536,0);long long point_constraints=0,marked=0;for(int m=1;m<=6;++m){FField F{m,1<<m,IRR[m]};int n=F.n;for(int ax=0;ax<=n;++ax)for(int by=0;by<=n;++by){int X=ax==n?0:ax,Y=by==n?0:by;int powx[4],powy[4];powx[0]=powy[0]=1;for(int t=1;t<4;++t){powx[t]=F.mul(powx[t-1],X);powy[t]=F.mul(powy[t-1],Y);}vector<int> rows(3*m,0);for(int i=0;i<4;++i)for(int j=0;j<4;++j){int ie=ax==n?3-i:i,je=by==n?3-j:j,idx=i*4+j;int v=F.mul(powx[ie],powy[je]);int dx=ie?F.mul(powx[ie-1],powy[je]):0;if(!(ie&1))dx=0;int dy=je?F.mul(powx[ie],powy[je-1]):0;if(!(je&1))dy=0;for(int t=0;t<m;++t){if(v>>t&1)rows[t]|=1<<idx;if(dx>>t&1)rows[m+t]|=1<<idx;if(dy>>t&1)rows[2*m+t]|=1<<idx;}}mark_kernel(sing,cert,rows,m,ax,by);++point_constraints;}
 int ns=accumulate(sing.begin()+1,sing.end(),0);cerr<<"m="<<m<<" sample-points="<<point_constraints<<" singular-labelled="<<ns<<" candidate="<<65535-ns<<"\n";
 }
 ofstream witnesses("singular_witnesses.tsv");for(int msk=1;msk<65536;++msk)if(sing[msk]){int v=cert[msk];assert(v);witnesses<<msk<<" "<<(v>>16)<<" "<<((v>>8)&255)<<" "<<(v&255)<<"\n";}witnesses.close();map<pair<int,int>,int> dist, reps; map<tuple<int,int,int>,int>dist3;map<tuple<int,int,int>,int> n1joint;int nsmooth=0;ofstream candidates("candidates.txt");for(int mask=1;mask<65536;++mask)if(!sing[mask]){nsmooth++;candidates<<mask<<'\n';auto H=hasse(mask),P=H;int a=4-rank4(H);for(int t=1;t<4;++t)P=matmult(P,H);int f=rank4(P),n1=points1(mask);dist[{f,a}]++;dist3[{f,a,n1}]++;n1joint[{f,a,n1}]++;}cout<<"CANDIDATES "<<nsmooth<<"\n";for(auto [p,n]:dist)cout<<"f="<<p.first<<" a="<<p.second<<" equations="<<n<<"\n";cout<<"N1_JOINT\n";for(auto [p,n]:n1joint)cout<<get<0>(p)<<","<<get<1>(p)<<","<<get<2>(p)<<":"<<n<<"\n";return 0;}
